const origin=process.env.ZASP_PUBLIC_ORIGIN,token=process.env.ZASP_CANARY_READ_TOKEN;
const required=['strict-transport-security','content-security-policy','x-frame-options','x-content-type-options','referrer-policy','permissions-policy'];
const start=Date.now();
const web=await fetch(origin+'/sign-in',{redirect:'manual',signal:AbortSignal.timeout(5000)});
if(web.status!==200||required.some(name=>!web.headers.has(name)))process.exit(1);
const api=await fetch(origin+'/api/v1/home/summary',{headers:{authorization:'Bearer '+token},signal:AbortSignal.timeout(5000)});
if(api.status!==200||!api.headers.has('x-correlation-id')||!api.headers.has('traceparent'))process.exit(1);
console.log(JSON.stringify({event:'readonly_canary',ok:true,duration_ms:Date.now()-start,correlation_id:api.headers.get('x-correlation-id')}));

annotations.nginx.ingress.kubernetes.io/configuratio:
add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
add_header Content-Security-Policy "default-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'; object-src 'none'; connect-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'" always;
add_header X-Frame-Options "DENY" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;
add_header Permissions-Policy "camera=(), microphone=(), geolocation=(), payment=(), usb=()" always;

add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "no-referrer" always;

